const officerFortifyWords={"ru":["Эквивалент в предметах опыта","Если использовать только выбранный вид предмета, с округлением вверх.","В начале боя титаны и самолёты получают щит от своего здоровья на 10 секунд.","В первые 10 секунд два крупнейших отряда среднего и дальнего боя получают щит от своей атаки.","Увеличивает атаку всех войск и урон по целям со щитом.","Повышает здоровье ближнего боя; войска ближнего боя принимают часть урона других войск, титанов и самолётов."],"en":["Equivalent XP items","Using only one item type, rounded up.","At battle start, Titans and warplanes receive an HP-based shield for 10 seconds.","For the first 10 seconds, the two largest mid- and long-range groups receive an attack-based shield.","Increases all troops' attack and damage against shielded targets.","Increases melee HP; melee troops share some damage of other troops, Titans and warplanes."],"es":["Equivalente en objetos de EXP","Usando solo un tipo de objeto, redondeado hacia arriba.","Al inicio, titanes y aviones reciben un escudo según su salud durante 10 s.","Durante los primeros 10 s, los dos grupos más numerosos de media y larga distancia reciben un escudo según su ataque.","Aumenta ataque de todas las tropas y daño a objetivos con escudo.","Aumenta la salud cuerpo a cuerpo; estas tropas comparten parte del daño de otras tropas, titanes y aviones."],"vi":["Vật phẩm EXP tương đương","Chỉ dùng một loại vật phẩm, làm tròn lên.","Khi bắt đầu trận, titan và máy bay nhận khiên theo máu trong 10 giây.","Trong 10 giây đầu, hai nhóm trung và tầm xa đông nhất nhận khiên theo tấn công.","Tăng tấn công toàn quân và sát thương lên mục tiêu có khiên.","Tăng máu cận chiến; quân cận chiến chia sẻ một phần sát thương của quân khác, titan và máy bay."],"ar":["ما يعادلها من عناصر الخبرة","باستخدام نوع واحد من العناصر، مع التقريب للأعلى.","عند بدء المعركة يحصل العمالقة والطائرات على درع حسب صحتهم لمدة 10 ثوان.","خلال أول 10 ثوان تحصل أكبر مجموعتين متوسطتي وبعيدتي المدى على درع حسب هجومهما.","يزيد هجوم كل القوات والضرر ضد الأهداف المحمية بدرع.","يزيد صحة القتال القريب؛ وتتحمل قواته جزءاً من ضرر القوات الأخرى والعمالقة والطائرات."],"zh":["等效經驗道具","僅使用一種道具，數量向上取整。","戰鬥開始時，泰坦和戰機獲得依生命值計算的護盾，持續10秒。","前10秒內，中遠程數量最多的兩支部隊獲得依攻擊計算的護盾。","提升全體部隊攻擊及對有護盾目標的傷害。","提升近戰生命，近戰部隊分擔其他部隊、泰坦及戰機受到的部分傷害。"],"hr":["Ekvivalentni predmeti iskustva","Uz samo jednu vrstu predmeta, zaokruženo naviše.","Na početku bitke titani i zrakoplovi dobivaju štit prema zdravlju na 10 s.","Prvih 10 s dvije najveće skupine srednjeg i dugog dometa dobivaju štit prema napadu.","Povećava napad svih postrojbi i štetu ciljevima sa štitom.","Povećava zdravlje bliske borbe; te postrojbe preuzimaju dio štete drugih postrojbi, titana i zrakoplova."],"it":["Oggetti PE equivalenti","Usando un solo tipo di oggetto, arrotondato per eccesso.","All'inizio della battaglia titani e aerei ricevono uno scudo basato sulla salute per 10 s.","Nei primi 10 s i due gruppi più numerosi di media e lunga distanza ricevono uno scudo basato sull'attacco.","Aumenta l'attacco di tutte le truppe e il danno ai bersagli con scudo.","Aumenta la salute corpo a corpo; tali truppe condividono parte dei danni di altre truppe, titani e aerei."]};
const officerFortifyItems=[[0,500,150],[0,1000,300],[0,3000,900],[1,50,500]];
function officerFortifyItemsView(result,cost,L,t,node,row,fmt){const w=officerFortifyWords[L]||officerFortifyWords.en,d=node('details','epBreakdown');d.append(node('summary','',w[0]));for(const [kind,xp,value] of officerFortifyItems)row(d,t[kind?3:2]+' '+fmt(xp),fmt(Math.ceil(cost/value)));d.append(node('p','epSmall',w[1]));result.append(d);}
